-- ============================================================================
-- StoreFlow consumer 2,000명 시드
-- 공통 테스트 비밀번호: test1234
--
-- 실행 전:
--   1) 사용할 DB를 선택하거나 USE <DB명>; 실행
--   2) Safe Update 오류 방지를 위해 이 파일에서 일시 해제
-- ============================================================================

SET NAMES utf8mb4;
SET SQL_SAFE_UPDATES = 0;

-- 기존 테스트/시드 consumer 정리
DROP TEMPORARY TABLE IF EXISTS _seed_consumer_ids;
CREATE TEMPORARY TABLE _seed_consumer_ids (
    consumer_id BIGINT PRIMARY KEY
);

SELECT consumer_id
FROM consumer
WHERE phone_number LIKE '010-8000-%'
   OR phone_number LIKE '010-8001-%'
   OR phone_number IN (
       '010-1000-0001','010-1000-0002','010-1000-0003','010-1000-0004','010-1000-0005',
       '010-1000-0006','010-1000-0007','010-1000-0008','010-1000-0009','010-1000-0010',
       '010-1000-0011','010-1000-0012','010-1000-0013','010-1000-0014','010-1000-0015',
       '010-1000-0016','010-1000-0017','010-1000-0018','010-1000-0019'
   );

DELETE oi
FROM order_item oi
JOIN orders o ON o.order_id = oi.order_id
JOIN _seed_consumer_ids s ON s.consumer_id = o.consumer_id;

DELETE ci
FROM cart_item ci
JOIN _seed_consumer_ids s ON s.consumer_id = ci.consumer_id;

DELETE o
FROM orders o
JOIN _seed_consumer_ids s ON s.consumer_id = o.consumer_id;

DELETE c
FROM consumer c
JOIN _seed_consumer_ids s ON s.consumer_id = c.consumer_id;

DROP TEMPORARY TABLE _seed_consumer_ids;

START TRANSACTION;






COMMIT;

-- 검증
SELECT COUNT(*) AS seeded_consumer_count
FROM consumer
WHERE phone_number LIKE '010-8000-%'
   OR phone_number LIKE '010-8001-%';

SET SQL_SAFE_UPDATES = 1;
